<?php
declare(strict_types=1);namespace App\Services;use App\Config\Database;use App\Support\Reference;use PDO;use RuntimeException;
final class DispatchService{
 private static function op(string$p):void{if(!Auth::hasRole('MCCOLLIN_OPERATIONS')||!Auth::can($p))throw new RuntimeException('Operations dispatch permission required.');}
 private static function role():?int{foreach(Auth::context()['roles']??[]as$r)if(in_array($r['role_code'],['MCCOLLIN_OPERATIONS','DRIVER'],true))return(int)$r['user_role_id'];return null;}
 public static function assignments():array{self::op('SHIPMENT_MANAGE');return Database::connection()->query("SELECT a.assignment_id,a.assignment_ref,l.load_ref,l.cargo_summary,t.registration_number,u.display_name driver_name FROM assignments a JOIN loads l ON l.load_id=a.load_id JOIN trucks t ON t.truck_id=a.truck_id JOIN drivers d ON d.driver_id=a.driver_id JOIN users u ON u.user_id=d.user_id LEFT JOIN shipments s ON s.active_assignment_id=a.assignment_id WHERE a.assignment_status='assigned' AND a.status='active' AND s.shipment_id IS NULL ORDER BY a.assigned_at")->fetchAll();}
 public static function create(int$assignmentId,string$depart,string$arrive,array$stops,int$uid):int{self::op('SHIPMENT_MANAGE');$d=strtotime($depart);$a=strtotime($arrive);if(!$d||!$a||$a<=$d)throw new RuntimeException('Planned arrival must be after departure.');$pdo=Database::connection();$pdo->beginTransaction();try{$st=$pdo->prepare("SELECT a.*,l.customer_company_id,l.origin_address_id,l.destination_address_id,l.current_status,oa.line_1 ol,oa.city oc,da.line_1 dl,da.city dc FROM assignments a JOIN loads l ON l.load_id=a.load_id JOIN addresses oa ON oa.address_id=l.origin_address_id JOIN addresses da ON da.address_id=l.destination_address_id LEFT JOIN shipments s ON s.active_assignment_id=a.assignment_id WHERE a.assignment_id=? AND s.shipment_id IS NULL FOR UPDATE");$st->execute([$assignmentId]);$x=$st->fetch();if(!$x||$x['assignment_status']!=='assigned'||$x['current_status']!=='assigned')throw new RuntimeException('Only an unplanned active assignment may create a shipment.');$pdo->prepare("INSERT INTO shipments(shipment_ref,load_id,customer_company_id,active_assignment_id,current_status,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,'planned','active',?,?)")->execute([Reference::make('SHP'),$x['load_id'],$x['customer_company_id'],$assignmentId,$uid,$uid]);$sid=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO trips(trip_ref,shipment_id,assignment_id,carrier_company_id,carrier_user_id,driver_id,truck_id,origin_address_id,destination_address_id,planned_departure_at,planned_arrival_at,current_status,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,'planned','active',?,?)")->execute([Reference::make('TRP'),$sid,$assignmentId,$x['carrier_company_id'],$x['carrier_user_id'],$x['driver_id'],$x['truck_id'],$x['origin_address_id'],$x['destination_address_id'],gmdate('Y-m-d H:i:s',$d),gmdate('Y-m-d H:i:s',$a),$uid,$uid]);$tid=(int)$pdo->lastInsertId();$all=[['pickup',$x['ol'],$x['oc'],gmdate('Y-m-d H:i:s',$d),'Pickup']];foreach($stops as$s)if(trim((string)($s['name']??''))!=='')$all[]=['intermediate',trim($s['address']??''),trim($s['city']??''),null,trim($s['name'])];$all[]=['destination',$x['dl'],$x['dc'],gmdate('Y-m-d H:i:s',$a),'Destination'];$ins=$pdo->prepare("INSERT INTO stops(stop_ref,trip_id,sequence_no,stop_type,name,address_line,city,planned_at,instructions,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,?,?,?,?,?,'active',?,?)");foreach($all as$i=>$s)$ins->execute([Reference::make('STP'),$tid,$i+1,$s[0],$s[4],$s[1],$s[2],$s[3],null,$uid,$uid]);$pdo->prepare("UPDATE loads SET current_status='planned',updated_by_user_id=?,row_version=row_version+1 WHERE load_id=? AND current_status='assigned'")->execute([$uid,$x['load_id']]);self::milestone($pdo,$sid,$tid,'planned',$uid);self::hist($pdo,'trip',$tid,null,'planned',$uid,'Shipment and trip planned');self::audit($pdo,'SHIPMENT_TRIP_CREATED',$tid,$uid,['shipment_id'=>$sid,'assignment_id'=>$assignmentId]);$pdo->commit();return$tid;}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
 public static function listAll():array{self::op('TRIP_VIEW_OPERATIONS');return Database::connection()->query(self::sql()." ORDER BY tr.created_at DESC")->fetchAll();}
 public static function driverTrips(int$uid):array{$st=Database::connection()->prepare(self::sql()." WHERE d.user_id=? ORDER BY tr.created_at DESC");$st->execute([$uid]);return$st->fetchAll();}
 public static function find(int$id):?array{$st=Database::connection()->prepare(self::sql()." WHERE tr.trip_id=? LIMIT 1");$st->execute([$id]);$r=$st->fetch();return$r?:null;}
 public static function transition(int$id,string$to,int$uid,bool$operations=false):void{$allowed=['planned'=>['driver_ready'],'driver_ready'=>['dispatched'],'dispatched'=>['in_transit'],'in_transit'=>['arrived'],'arrived'=>['delivered']];if($operations)self::op($to==='dispatched'?'TRIP_DISPATCH':'TRIP_STATUS_OPERATIONS');elseif(!Auth::hasRole('DRIVER')||!Auth::can('TRIP_STATUS_DRIVER'))throw new RuntimeException('Driver trip permission required.');$pdo=Database::connection();$pdo->beginTransaction();try{$st=$pdo->prepare("SELECT tr.*,d.user_id driver_user,l.load_id FROM trips tr JOIN drivers d ON d.driver_id=tr.driver_id JOIN shipments sh ON sh.shipment_id=tr.shipment_id JOIN loads l ON l.load_id=sh.load_id WHERE tr.trip_id=? FOR UPDATE");$st->execute([$id]);$r=$st->fetch();if(!$r||!in_array($to,$allowed[$r['current_status']]??[],true))throw new RuntimeException('Invalid trip transition.');if(!$operations&&(int)$r['driver_user']!==$uid)throw new RuntimeException('Only the assigned Driver may update this trip.');if(!$operations&&$to==='dispatched')throw new RuntimeException('Only Operations may dispatch.');$extra=$to==='driver_ready'?',driver_ready_at=UTC_TIMESTAMP(6)':($to==='dispatched'?',dispatched_at=UTC_TIMESTAMP(6),dispatched_by_user_id='.(int)$uid:($to==='arrived'?',arrived_at=UTC_TIMESTAMP(6)':($to==='delivered'?',delivered_at=UTC_TIMESTAMP(6),completed_at=UTC_TIMESTAMP(6)':'')));$pdo->exec("UPDATE trips SET current_status=".$pdo->quote($to).",last_status_by_user_id=".(int)$uid.$extra.",updated_by_user_id=".(int)$uid.",row_version=row_version+1 WHERE trip_id=".(int)$id);$ship=$to==='delivered'?'delivered_pending_epod':$to;$pdo->prepare("UPDATE shipments SET current_status=?,dispatched_at=IF(?='dispatched',UTC_TIMESTAMP(6),dispatched_at),delivered_at=IF(?='delivered',UTC_TIMESTAMP(6),delivered_at),updated_by_user_id=?,row_version=row_version+1 WHERE shipment_id=?")->execute([$ship,$to,$to,$uid,$r['shipment_id']]);$pdo->prepare("UPDATE loads SET current_status=?,updated_by_user_id=?,row_version=row_version+1 WHERE load_id=?")->execute([$ship,$uid,$r['load_id']]);self::milestone($pdo,(int)$r['shipment_id'],$id,$ship,$uid);self::hist($pdo,'trip',$id,$r['current_status'],$to,$uid,'Trip status updated');self::audit($pdo,'TRIP_STATUS_UPDATED',$id,$uid,['from'=>$r['current_status'],'to'=>$to]);NotificationService::tripEvent($pdo,$id,'Trip status updated','Trip '.$r['trip_ref'].' is now '.str_replace('_',' ',$ship).'.',$uid,$to==='delivered'?'high':'normal');$pdo->commit();}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
 public static function shipperTrips(int$companyId):array{$st=Database::connection()->prepare(self::sql()." WHERE sh.customer_company_id=? ORDER BY tr.created_at DESC");$st->execute([$companyId]);return$st->fetchAll();}
 public static function carrierTrips(int$uid):array{$p=CarrierOnboarding::current($uid);if(!$p)return[];$col=$p['owner_type']==='company'?'tr.carrier_company_id':'tr.carrier_user_id';$val=$p['owner_type']==='company'?(int)$p['subject_id']:$uid;$st=Database::connection()->prepare(self::sql()." WHERE {$col}=? ORDER BY tr.created_at DESC");$st->execute([$val]);return$st->fetchAll();}
 public static function stops(int$id):array{$st=Database::connection()->prepare("SELECT * FROM stops WHERE trip_id=? AND status='active' ORDER BY sequence_no");$st->execute([$id]);return$st->fetchAll();}
 private static function sql():string{return"SELECT tr.*,sh.shipment_ref,sh.current_status shipment_status,l.load_ref,l.cargo_summary,oa.city origin_city,da.city destination_city,t.registration_number,u.display_name driver_name FROM trips tr JOIN shipments sh ON sh.shipment_id=tr.shipment_id JOIN loads l ON l.load_id=sh.load_id JOIN addresses oa ON oa.address_id=tr.origin_address_id JOIN addresses da ON da.address_id=tr.destination_address_id JOIN trucks t ON t.truck_id=tr.truck_id JOIN drivers d ON d.driver_id=tr.driver_id JOIN users u ON u.user_id=d.user_id";}
 private static function milestone(PDO$p,int$s,int$t,string$c,int$u):void{$p->prepare("INSERT INTO shipment_milestones(shipment_milestone_ref,shipment_id,trip_id,milestone_code,occurred_at,actor_user_id,metadata_json,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,UTC_TIMESTAMP(6),?,?,'active',?,?)")->execute([Reference::make('MIL'),$s,$t,$c,$u,json_encode(['phase'=>8]),$u,$u]);}
 private static function hist(PDO$p,string$e,int$i,?string$o,string$n,int$u,string$r):void{$p->prepare("INSERT INTO status_history(status_history_ref,entity_type,entity_id_value,previous_status,new_status,actor_user_id,actor_user_role_id,source_channel,reason,occurred_at,status,created_by_user_id) VALUES(?,?,?,?,?,?,?,'web',?,UTC_TIMESTAMP(6),'active',?)")->execute([Reference::make('STH'),$e,$i,$o,$n,$u,self::role(),$r,$u]);}
 private static function audit(PDO$p,string$a,int$i,int$u,array$x):void{$p->prepare("INSERT INTO audit_events(audit_event_ref,metadata_json,status,created_by_user_id) VALUES(?,?,'active',?)")->execute([Reference::make('AUD'),json_encode(array_merge(['action_code'=>$a,'entity_id'=>$i],$x)), $u]);}
}
